theme.css:
/* theme: Copper Ledger | A market rattled by a record heist and shattered chips, while a World Series win offers the only bright spot in an amber-braced tape. */
/* mood: tense */
/* layout: hero=split; political-news=lede/stack; financial-news=stat/stack; entertainment-news=tile/grid-3; sports=outline/feature; music-releases=plain/stack; stock-analysis=numbered/grid-2; outlook=timeline/stack */

.diary-page {
  --paper: #1a1408;
  --paper-alt: #241c0d;
  --ink: #f7ecd6;
  --ink-soft: #d8cbb0;
  --muted: #a8976f;
  --accent: #ffad33;
  --accent-ink: #1a1408;
  --rule: #433822;
  --font-display: var(--ff-syne), sans-serif;
  --font-body: var(--ff-newsreader), Georgia, serif;
  --font-ui: var(--ff-space-grotesk), system-ui, sans-serif;
  background: var(--paper);
  color: var(--ink-soft);
}

@media (min-width: 1024px) {
  .diary-page[data-hero="split"] .diary-hero-inner {
    grid-template-columns: minmax(0, 1.4fr) minmax(0, 1fr);
    column-gap: 5rem;
  }
}

.diary-page .diary-hero {
  background: linear-gradient(135deg, #241c0d 0%, #1a1408 60%, #2e220c 100%);
  border-bottom: 1px solid var(--rule);
  position: relative;
}

.diary-page .diary-hero-inner {
  padding-block: 3rem 4.5rem;
}

.diary-page .diary-kicker {
  font-family: var(--font-ui);
  letter-spacing: 0.3em;
  font-size: 0.72rem;
  color: var(--accent);
  font-weight: 700;
}

.diary-page .diary-title {
  font-family: var(--font-display);
  font-weight: 800;
  font-size: clamp(2.6rem, 6vw, 4.5rem);
  letter-spacing: -0.02em;
  line-height: 1.05;
  color: var(--ink);
  position: relative;
}

.diary-page .diary-title::before {
  content: "";
  position: absolute;
  top: -0.5rem;
  left: 0;
  width: 4.5rem;
  height: 0.35rem;
  background: var(--accent);
}

.diary-page .diary-summary {
  font-family: var(--font-body);
  font-size: clamp(1.15rem, 2vw, 1.35rem);
  line-height: 1.6;
  color: var(--ink-soft);
  border-left: 3px solid var(--accent);
  padding-left: 1.25rem;
  margin-top: 1.75rem;
}

.diary-page .diary-theme-note {
  margin-top: 1.5rem;
  font-family: var(--font-ui);
  font-size: 0.82rem;
  color: var(--muted);
}

.diary-page .diary-theme-name {
  background: var(--accent);
  color: var(--accent-ink);
  font-family: var(--font-ui);
  font-weight: 700;
  font-size: 0.72rem;
  letter-spacing: 0.12em;
  text-transform: uppercase;
  padding: 0.2rem 0.7rem;
  border-radius: 2px;
}

.diary-page .diary-toc {
  border-bottom-color: var(--rule);
  background: #1a1408;
}

.diary-page .diary-toc-link,
.diary-page .diary-toc-top,
.diary-page .diary-toc-bottom {
  color: var(--muted);
  font-family: var(--font-ui);
  font-size: 0.82rem;
}

.diary-page .diary-toc-number {
  color: var(--accent);
  font-weight: 700;
}

.diary-page .diary-toc-link:hover,
.diary-page .diary-toc-top:hover,
.diary-page .diary-toc-bottom:hover,
.diary-page .diary-toc-link.is-active {
  color: var(--ink);
}

@media (min-width: 1024px) {
  .diary-page .diary-toc-list {
    border-left-color: var(--rule);
  }
  .diary-page .diary-toc-link.is-active {
    border-left-color: var(--accent);
  }
  .diary-page .diary-toc-label {
    color: var(--muted);
  }
}

.diary-page .diary-section {
  border-top-color: var(--rule);
  padding-block: 3.5rem;
}

.diary-page .diary-section-number {
  color: var(--accent);
  font-family: var(--font-ui);
  font-weight: 700;
  font-size: 0.74rem;
  letter-spacing: 0.18em;
}

.diary-page .diary-section-title {
  font-family: var(--font-display);
  font-weight: 800;
  font-size: clamp(1.9rem, 3.4vw, 2.6rem);
  letter-spacing: -0.015em;
  color: var(--ink);
}

.diary-page .diary-section-head {
  border-bottom: 2px solid var(--rule);
  padding-bottom: 1rem;
  margin-bottom: 2rem;
}

/* TOC top/bottom positions */
.diary-page .diary-toc-top,
.diary-page .diary-toc-bottom {
  font-size: 0.8rem;
  color: var(--muted);
}

.diary-page .diary-toc-top:hover,
.diary-page .diary-toc-bottom:hover {
  color: var(--accent);
}

/* Card base adjustments */
.diary-page .diary-card-title {
  font-family: var(--font-display);
  font-weight: 700;
  color: var(--ink);
  letter-spacing: -0.01em;
}

.diary-page .diary-card-body {
  font-size: 1.05rem;
  line-height: 1.7;
  color: var(--ink-soft);
}

.diary-page .diary-card-thread {
  border-color: var(--accent);
  color: var(--accent);
  font-family: var(--font-ui);
  font-size: 0.72rem;
  font-weight: 600;
}

.diary-page .diary-card-thread:hover {
  background: var(--accent);
  color: var(--accent-ink);
}

/* Lede cards (political-news) */
.diary-page [data-section="political-news"] .diary-card-lede {
  border-left: 3px solid var(--accent);
  font-family: var(--font-display);
  font-size: 1.35rem;
  line-height: 1.5;
  color: var(--ink);
  padding-left: 1.25rem;
}

.diary-page [data-section="political-news"] .diary-card-inner {
  padding-block: 1rem;
  border-top: 1px solid var(--rule);
}

.diary-page [data-section="political-news"] .diary-card-body {
  font-size: 1.15rem;
}

/* Stat cards (financial-news) */
.diary-page [data-section="financial-news"] .diary-card-inner {
  border-top: 3px solid var(--accent);
  padding-top: 1.25rem;
}

.diary-page [data-section="financial-news"] .diary-card-figure {
  font-family: var(--font-display);
  font-size: clamp(2.6rem, 12cqi, 4rem);
  font-weight: 800;
  line-height: 1;
  letter-spacing: -0.03em;
  color: var(--accent);
}

.diary-page [data-section="financial-news"] .diary-card-body {
  font-size: 1.15rem;
  line-height: 1.75;
}

/* Tile cards (entertainment-news) */
.diary-page [data-section="entertainment-news"] .diary-card-inner {
  background: var(--paper-alt);
  padding: 1.75rem;
  position: relative;
  border-radius: 0;
  border: 1px solid var(--rule);
}

.diary-page [data-section="entertainment-news"] .diary-card-inner::after {
  content: "";
  position: absolute;
  bottom: 0;
  left: 0;
  right: 0;
  height: 3px;
  background: var(--accent);
}

.diary-page [data-section="entertainment-news"] .diary-card-title {
  font-size: 1.35rem;
  line-height: 1.25;
}

.diary-page [data-section="entertainment-news"] .diary-card-body {
  font-size: 1rem;
  line-height: 1.65;
}

/* Outline cards (sports) */
.diary-page [data-section="sports"] .diary-card-inner {
  padding: 1.5rem;
  border: 1px solid var(--rule);
  position: relative;
  background:  #1a1408;
}

.diary-page [data-section="sports"] .diary-card-inner::before {
  content: "";
  position: absolute;
  top: -1px;
  left: -1px;
  width: 2.5rem;
  height: 2.5rem;
  border-top: 3px solid var(--accent);
  border-left: 3px solid var(--accent);
}

.diary-page [data-section="sports"] .diary-card-title {
  font-size: 1.5rem;
  padding-top: 0.5rem;
}

.diary-page [data-section="sports"] .diary-card-body {
  font-size: 1.02rem;
  line-height: 1.68;
}

/* Numbered cards (stock-analysis) */
.diary-page [data-section="stock-analysis"] .diary-card-inner {
  grid-template-columns: auto minmax(0, 1fr);
  column-gap: 1.5rem;
}

.diary-page [data-section="stock-analysis"] .diary-card-index {
  font-family: var(--font-display);
  font-size: 2.8rem;
  font-weight: 800;
  color: var(--accent);
  line-height: 0.9;
}

.diary-page [data-section="stock-analysis"] .diary-card-title {
  font-size: 1.2rem;
}

.diary-page [data-section="stock-analysis"] .diary-card-body {
  font-size: 0.98rem;
  line-height: 1.62;
}

.diary-page [data-section="stock-analysis"] .diary-card-inner {
  border-left: 2px solid var(--rule);
  padding-left: 1rem;
}

/* Timeline cards (outlook) */
.diary-page [data-section="outlook"] .diary-card-inner {
  position: relative;
  padding-left: 2rem;
}

.diary-page [data-section="outlook"] .diary-card-inner::before {
  content: "";
  position: absolute;
  left: 0.4rem;
  top: 0.3rem;
  bottom: -1.5rem;
  width: 2px;
  background: var(--rule);
}

.diary-page [data-section="outlook"] .diary-card:last-child .diary-card-inner::before {
  bottom: 0;
}

.diary-page [data-section="outlook"] .diary-card-inner::after {
  content: "";
  position: absolute;
  left: 0;
  top: 0.6rem;
  width: 0.9rem;
  height: 0.9rem;
  border-radius: 50%;
  background: var(--accent);
  box-shadow: 0 0 0 4px var(--paper);
}

.diary-page [data-section="outlook"] .diary-card-title {
  font-size: 1.2rem;
}

.diary-page [data-section="outlook"] .diary-card-body {
  font-size: 1rem;
  line-height: 1.65;
}

/* Music releases: plain, players stand alone */
.diary-page [data-section="music-releases"] .diary-card-inner {
  gap: 0.35rem;
}

.diary-page [data-section="music-releases"] .diary-card-title {
  font-size: 1.25rem;
}

.diary-page [data-section="music-releases"] .diary-card-body {
  font-size: 1.05rem;
}

.diary-page [data-section="music-releases"] .diary-stories--stack > .diary-card--plain + .diary-card--plain {
  border-top-color: var(--rule);
}

/* Markets section */
.diary-page .diary-markets {
  gap: 0.8rem;
  margin-bottom: 2.5rem;
}

.diary-page .diary-markets-label {
  color: var(--muted);
  font-family: var(--font-ui);
  letter-spacing: 0.14em;
  font-size: 0.72rem;
  font-weight: 600;
}

.diary-page .diary-spark {
  background: var(--paper-alt);
  border-color: var(--rule);
  border-radius: 0;
  padding: 0.9rem 1rem 0.7rem;
}

.diary-page .diary-spark-label {
  color: var(--muted);
  font-size: 0.75rem;
  font-family: var(--font-ui);
}

.diary-page .diary-spark-value {
  color: var(--ink);
  font-family: var(--font-ui);
  font-size: 0.95rem;
  font-weight: 600;
}

.diary-page .diary-spark-change {
  font-family: var(--font-ui);
  font-size: 0.75rem;
}

.diary-page .diary-spark.is-up {
  color: var(--accent);
}

.diary-page .diary-spark.is-down {
  color: var(--accent);
}

.diary-page .diary-spark.is-up .diary-spark-change {
  color: var(--accent);
}

.diary-page .diary-spark.is-down .diary-spark-change {
  color: var(--accent);
}

/* Prose */
.diary-page .diary-prose {
  color: var(--ink-soft);
}

.diary-page .diary-prose a {
  color: var(--accent);
  border-bottom: 1px solid currentColor;
  font-size: 0.66em;
  letter-spacing: 0.08em;
}

.diary-page .diary-prose a:hover {
  color: var(--ink);
}

.diary-page .diary-prose strong {
  color: var(--ink);
  font-weight: 600;
}

.diary-page .diary-prose blockquote {
  border-left-color: var(--accent);
  color: var(--ink);
}

.diary-page .diary-prose ul > li::before {
  background: var(--accent);
}

.diary-page .diary-prose ol > li::marker {
  color: var(--accent);
}

.diary-page .diary-prose h4 {
  color: var(--ink);
  font-family: var(--font-display);
  font-size: 1.25rem;
  font-weight: 700;
  line-height: 1.3;
}

/* Drop cap */
.diary-page .diary-section:first-child .diary-card--plain:first-child .diary-prose > p:first-of-type::first-letter {
  font-family: var(--font-display);
  font-weight: 800;
  color: var(--accent);
}

/* Footer */
.diary-page .diary-footer {
  border-top-color: var(--rule);
  color: var(--muted);
  font-family: var(--font-ui);
  font-size: 0.82rem;
}

.diary-page .diary-footer a {
  color: var(--ink);
  font-weight: 600;
}

.diary-page .diary-footer a:hover {
  color: var(--accent);
}

.diary-page .diary-crumbs a {
  color: var(--muted);
  font-family: var(--font-ui);
  font-size: 0.82rem;
}

.diary-page .diary-crumbs a:hover {
  color: var(--accent);
}

/* Section number in TOC is accent */
/* Feature layout for sports: first card full width, rest below */
@container article (min-width: 40rem) {
  .diary-page .diary-stories--feature > .diary-card:first-child .diary-card-inner {
    padding: 2.25rem;
  }

  .diary-page .diary-stories--feature > .diary-card:first-child .diary-card-title {
    font-size: 1.9rem;
  }

  .diary-page .diary-stories--feature > .diary-card:first-child .diary-card-body {
    font-size: 1.1rem;
    line-height: 1.75;
  }
}

/* Grid 3 for entertainment: on medium+ widen */
@container article (min-width: 40rem) {
  .diary-page .diary-stories--grid-3 {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }
}

@container article (min-width: 54rem) {
  .diary-page .diary-stories--grid-3 {
    grid-template-columns: repeat(3, minmax(0, 1fr));
  }
}

/* Stack sections */
.diary-page .diary-stories--stack {
  max-width: 46rem;
}

.diary-page .diary-stories--stack > .diary-card--plain + .diary-card--plain {
  border-top-color: var(--rule);
}

/* Hover subtle lift for tiled cards (entertainment) and outline (sports) */
.diary-page [data-section="entertainment-news"] .diary-card,
.diary-page [data-section="sports"] .diary-card {
  transition: transform 200ms ease, border-color 200ms ease;
}

.diary-page [data-section="entertainment-news"] .diary-card:hover,
.diary-page [data-section="sports"] .diary-card:hover {
  transform: translateY(-2px);
  border-color: var(--accent);
}

/* keep the toc numbers tied to section numbers */
.diary-page .diary-toc-number {
  font-variant-numeric: tabular-nums;
}

/* Ensure plain music cards don't get boxed by base */
.diary-page [data-section="music-releases"] .diary-card--plain .diary-card-inner {
  padding: 0;
  background: none;
  border: 0;
  box-shadow: none;
}

/* Pull section head closer to its list for numbered sections */
.diary-page [data-section="stock-analysis"] .diary-section-head {
  margin-bottom: 1.5rem;
}

/* No extra bottom margins in spine for outlook */
.diary-page [data-section="outlook"] .diary-stories--stack {
  gap: 2.25rem;
}
